  const away = $('Parse Teams').item.json.away_team || '';
  const home = $('Parse Teams').item.json.home_team || '';
  const wh   = $('Webhook').item.json.body ?? $('Webhook').item.json;
  const odds = wh.odds || 'Not provided';

  // Fuzzy team matcher (mirrors Match Kalshi Teams / Filter CFBD Games)
  const matchesTeam = (candidate, team) => {
    const c = (candidate || '').toLowerCase();
    const t = (team || '').toLowerCase();
    if (!c || !t) return false;
    if (c.includes(t) || t.includes(c)) return true;
    const words = t.split(/\s+/).filter(w =>
      w.length > 3 &&
      !['the','and','for','with','city','team','state','university'].includes(w)
    );
    return words.some(w => c.includes(w));
  };

  let kalshiStr = 'No Kalshi market found for this game';
