const items    = $input.all();
const awayTeam = $('Parse Teams').item.json.away_team || '';
const homeTeam = $('Parse Teams').item.json.home_team || '';

// Return true if the market title contains at least one significant word from `team`
const titleMatchesTeam = (title, team) => {
  const ti = (title || '').toLowerCase();
  const t  = (team  || '').toLowerCase();
  if (!t || !ti) return false;
  if (ti.includes(t)) return true;
  const words = t.split(/\s+/).filter(w =>
    w.length > 3 &&
    !['the','and','for','with','city','team','state'].includes(w)
  );
  return words.some(w => ti.includes(w));
};

// Return true if `sub` (yes_sub_title / no_sub_title) contains a word from `team`
const subMatchesTeam = (sub, team) => {
  const s = (sub  || '').toLowerCase();
  const t = (team || '').toLowerCase();
  if (!s || !t) return false;
  if (s.includes(t) || t.includes(s)) return true;
  const words = t.split(/\s+/).filter(w =>
    w.length > 3 &&
    !['the','and','for','with','city','team','state'].includes(w)
  );
  return words.some(w => s.includes(w));
};

let kalshiEdge = null;

try {
  const cacheRow = items[0]?.json;
  const markets  = cacheRow?.data?.markets;

  if (Array.isArray(markets) && markets.length > 0 &&
      homeTeam && homeTeam !== 'General') {

    // Step 1 — find markets whose title mentions BOTH teams
    const gameMarkets = markets.filter(m =>
      titleMatchesTeam(m.title, awayTeam) &&
      titleMatchesTeam(m.title, homeTeam)
    );

    if (gameMarkets.length > 0) {
      // Step 2 — prefer the market where YES side = home team
      // Kalshi uses yes_sub_title e.g. "Indiana" for "Indiana wins?"
      const homeMarket =
        gameMarkets.find(m => subMatchesTeam(m.yes_sub_title, homeTeam)) ||
        gameMarkets[0];

      // Prices are dollar strings "0.52" meaning $0.52 per $1 contract = 52 % prob
      const yesDollars = homeMarket.yes_bid_dollars ?? homeMarket.last_price_dollars ?? null;
      const noDollars  = homeMarket.no_bid_dollars  ?? null;

      if (yesDollars !== null) {
        const yesProb = parseFloat(yesDollars) * 100;   // e.g. 52.0
        const noProb  = noDollars !== null
          ? parseFloat(noDollars) * 100
          : 100 - yesProb;

        kalshiEdge = {
          market:           homeMarket.title,
          ticker:           homeMarket.ticker,
          yes_team:         homeMarket.yes_sub_title || homeTeam,
          no_team:          homeMarket.no_sub_title  || awayTeam,
          yes_implied_pct:  yesProb.toFixed(1),   // home team win probability %
          no_implied_pct:   noProb.toFixed(1),    // away team win probability %
          yes_bid_dollars:  parseFloat(yesDollars).toFixed(2),
          no_bid_dollars:   noDollars !== null ? parseFloat(noDollars).toFixed(2) : null,
          volume:           parseFloat(homeMarket.volume_fp       ?? 0).toFixed(0),
          open_interest:    parseFloat(homeMarket.open_interest_fp ?? 0).toFixed(0),
          last_updated:     homeMarket.updated_time ?? null,
        };
      }
    }
  }
} catch(e) {
  // cache miss or malformed data — silently skip
}

return [{
  json: {
    ...(items[0]?.json || {}),
    kalshi_edge:      kalshiEdge,
    kalshi_available: kalshiEdge !== null,
  }
}];

// Derive the current CFBD week from /calendar at runtime — never hardcoded.
// The HTTP node emits one item per calendar entry.
const weeks = $input.all().map(i => i.json);
const now = Date.now();
const parse = s => (s ? new Date(s).getTime() : null);

const regular = weeks.filter(w => (w.seasonType || w.season_type) === 'regular');
const pool = regular.length ? regular : weeks;

let chosen = null;

// 1) now falls within [startDate, endDate]
for (const w of pool) {
  const start = parse(w.startDate || w.firstGameStart);
  const end   = parse(w.endDate   || w.lastGameStart);
  if (start !== null && end !== null && now >= start && now <= end) { chosen = w; break; }
}

// 2) otherwise the latest week that has already started
if (!chosen) {
  const started = pool
    .filter(w => { const s = parse(w.startDate || w.firstGameStart); return s !== null && s <= now; })
    .sort((a, b) => parse(a.startDate || a.firstGameStart) - parse(b.startDate || b.firstGameStart));
  if (started.length) chosen = started[started.length - 1];
}

// 3) fallback: first entry / week 1
if (!chosen) chosen = pool[0] || { week: 1 };

return [{ json: { year: 2026, week: chosen.week || 1 } }];

// Match the requested matchup against the week's FBS games.
// Fuzzy-matching mirrors the pattern in "Match Kalshi Teams".
const items    = $input.all();
const awayTeam = $('Parse Teams').item.json.away_team || '';
const homeTeam = $('Parse Teams').item.json.home_team || '';

const matchesTeam = (candidate, team) => {
  const c = (candidate || '').toLowerCase();
  const t = (team || '').toLowerCase();
  if (!c || !t) return false;
  if (c.includes(t) || t.includes(c)) return true;
  const words = t.split(/\s+/).filter(w =>
    w.length > 3 &&
    !['the', 'and', 'for', 'with', 'city', 'team', 'state', 'university'].includes(w)
  );
  return words.some(w => c.includes(w));
};

let matched = null;
for (const it of items) {
  const g = it.json;
  if (!g || !g.homeTeam || !g.awayTeam) continue;
  const hit =
    (matchesTeam(g.awayTeam, awayTeam) && matchesTeam(g.homeTeam, homeTeam)) ||
    (matchesTeam(g.awayTeam, homeTeam) && matchesTeam(g.homeTeam, awayTeam));
  if (hit) { matched = g; break; }
}

if (matched) {
  return [{ json: {
    matched:        true,
    id:             matched.id,
    week:           matched.week,
    startDate:      matched.startDate,
    neutralSite:    matched.neutralSite,
    conferenceGame: matched.conferenceGame,
    venue:          matched.venue,
    homeTeam:       matched.homeTeam,
    homeConference: matched.homeConference,
    awayTeam:       matched.awayTeam,
    awayConference: matched.awayConference,
  } }];
}

return [{ json: {
  matched:  false,
  gameNote: 'No matching FBS game found for ' + awayTeam + ' vs ' + homeTeam,
} }];
